class CommandCenterSingleInstanceGuard:
    """Keep one command-center owner per host/port in a Windows session."""

    ERROR_ALREADY_EXISTS = 183

    def __init__(self, host: str, port: int) -> None:
        self.name = command_center_instance_mutex_name(host, port)
        self._handle: int | None = None
        if os.name != "nt":
            return
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateMutexW.argtypes = (ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p)
        kernel32.CreateMutexW.restype = ctypes.c_void_p
        kernel32.CloseHandle.argtypes = (ctypes.c_void_p,)
        kernel32.CloseHandle.restype = ctypes.c_bool
        ctypes.set_last_error(0)
        handle = kernel32.CreateMutexW(None, False, self.name)
        error = ctypes.get_last_error()
        if not handle:
            raise OSError(error, f"Unable to create command-center instance mutex {self.name}")
        if error == self.ERROR_ALREADY_EXISTS:
            kernel32.CloseHandle(handle)
            raise RuntimeError(f"A command-center gateway already owns {host}:{port}")
        self._handle = int(handle)
        self._kernel32 = kernel32

    def close(self) -> None:
        if self._handle is None:
            return
        self._kernel32.CloseHandle(ctypes.c_void_p(self._handle))
        self._handle = None

    def __enter__(self) -> "CommandCenterSingleInstanceGuard":
        return self

    def __exit__(self, *_exc: Any) -> None:
        self.close()


def command_center_instance_mutex_name(host: str, port: int) -> str:
    endpoint = re.sub(r"[^A-Za-z0-9_.-]+", "_", f"{host}_{int(port)}")
    return rf"Local\NovaOpsCommandCenterGateway_{endpoint}"


class BoundedThreadingHTTPServer(ThreadingHTTPServer):
    """Apply backpressure instead of creating unlimited request threads."""

    daemon_threads = True
    request_queue_size = 32

    def __init__(self, *args: Any, max_request_threads: int = 32, **kwargs: Any) -> None:
        self._request_slots = BoundedSemaphore(max(1, int(max_request_threads)))
        super().__init__(*args, **kwargs)

    def process_request(self, request: Any, client_address: Any) -> None:
        self._request_slots.acquire()
        try:
            super().process_request(request, client_address)
        except Exception:
            self._request_slots.release()
            raise

    def process_request_thread(self, request: Any, client_address: Any) -> None:
        try:
            super().process_request_thread(request, client_address)
        finally:
            self._request_slots.release()

