    def _support_email_cache_guard(self) -> Lock:
        lock = getattr(self, "_support_email_intake_lock", None)
        if lock is None:
            # Production runtimes initialize this eagerly. The lazy branch keeps
            # isolated test runtimes and recovery tools on the same serialized
            # cache path without allowing an unlocked read/merge/write cycle.
            lock = Lock()
            self._support_email_intake_lock = lock
        return lock

