    def tickets(self) -> dict[str, Any]:
        # Cloud Run filesystems are ephemeral.  The ticket projection is also
        # stored as individual Firestore documents by the Salesforce ingest
        # lane, so prefer that durable projection whenever it is configured.
        firestore_cache = _firestore_ticket_cache()
        if firestore_cache is not None:
            return _filter_ticket_cache(firestore_cache)
        cache = _read_cached_json(
            self.tickets_path,
            {
                "ok": True,
                "status": "not_loaded",
                "updatedAtUtc": "",
                "generatedAt": "",
                "source": "No live command-center ticket cache has been loaded yet.",
                "columns": [],
                "agentActivity": [],
                "analytics": {},
            },
        )
        # After scale-to-zero the /tmp cache file is gone. Hydrate the board
        # from the durable Firestore store so the dashboard shows real tickets
        # on the first request instead of an empty board. Only triggers when
        # the local cache is genuinely missing, so a live instance never
        # re-reads Firestore on every poll.
        if not str(cache.get("updatedAtUtc") or "").strip() and not self.tickets_path.is_file():
            cache = self._tickets_from_firestore(cache)
        return _filter_ticket_cache(cache)

