    def dashboard_state(
        self,
        *,
        include_slow: bool = False,
        include_kpi: bool = False,
    ) -> dict[str, Any]:
        """Return one coherent read model for the frequently refreshed dashboard.

        The browser previously requested the same job collection through three
        independent polling loops while also polling tickets, review packets,
        chat, mail, and KPI caches.  Reading those projections together prevents
        overlapping requests from exhausting the bounded Cloud Run proxy.
        """

        snapshot: dict[str, Any] = {
            "ok": True,
            "schemaVersion": 1,
            "generatedAtUtc": _utc_now(),
            "health": self.health(),
            "jobs": self.jobs(limit=200),
            "reviewPackets": self.review_packets(),
            "agentChat": self.agent_chat(limit=120),
        }
        if include_slow:
            snapshot.update(
                {
                    "tickets": self.tickets(),
                    "emailWatch": self.email_watch(),
                    "inboxLedger": self.inbox_ledger_status(),
                    "schedule": self.schedule(),
                }
            )
        if include_kpi:
            snapshot["kpiDashboard"] = self.kpi_dashboard()
        return snapshot

