    def review_packets(self, *, include_private: bool = False) -> dict[str, Any]:
        """Return actionable review work, with internal execution context private by default."""

        cache = _read_cached_json(
            self.review_packets_path,
            {
                "ok": True,
                "status": "not_loaded",
                "updatedAtUtc": "",
                "summary": "No ticket review packets are waiting.",
                "packets": [],
            },
        )
        review_rows = self._durable_review_rows()
        unresolved_bridge_ids = {
            int(row.get("id") or 0)
            for row in review_rows
            if int(row.get("id") or 0) > 0
        }
        # Generic outcome reviews are derived exclusively from SQLite. Older
        # builds could also create a rich JSON packet for the same bridge job;
        # suppress that mirror whenever the durable ledger owns the review.
        packets = []
        for packet in cache.get("packets") or []:
            if (
                not isinstance(packet, dict)
                or str(packet.get("kind") or "") == "job_outcome"
                or str(packet.get("sourceType") or "").strip() in DIRECT_CHAT_SOURCE_TYPES
                or not _review_packet_has_substantive_result(packet)
            ):
                continue
            raw_bridge_job_id = str(packet.get("bridgeJobId") or "").strip()
            packet_bridge_job_id = int(raw_bridge_job_id) if raw_bridge_job_id.isdigit() else 0
            if packet_bridge_job_id > 0 and packet_bridge_job_id in unresolved_bridge_ids:
                continue
            packets.append(packet)
        represented_jobs = {
            int(str(packet.get("bridgeJobId") or "0"))
            for packet in packets
            if str(packet.get("bridgeJobId") or "").strip().isdigit()
            and int(str(packet.get("bridgeJobId") or "0")) > 0
        }
        if review_rows:
            for row in review_rows:
                bridge_job_id = int(row.get("id") or 0)
                if bridge_job_id <= 0 or bridge_job_id in represented_jobs:
                    continue
                source_record = self._job_record_for_review_row(row)
                if not _review_row_creates_packet(row, source_record):
                    continue
                durable_packet = _review_packet_from_ledger_job(row, source_record=source_record)
                ticket_key = _review_packet_ticket_key(durable_packet)
                if ticket_key:
                    # A durable non-success outcome is the authoritative review
                    # owner. Do not show an older static packet beside it.
                    packets = [
                        packet
                        for packet in packets
                        if _review_packet_ticket_key(packet) != ticket_key
                    ]
                packets.append(durable_packet)
        packets = _coalesce_recurring_review_packets(packets)
        packets.sort(key=lambda packet: str(packet.get("updatedAtUtc") or packet.get("createdAtUtc") or ""), reverse=True)
        cache["packets"] = packets if include_private else [_public_review_packet(packet) for packet in packets]
        cache["count"] = len(packets)
        cache["status"] = "ok" if packets else str(cache.get("status") or "empty")
        cache["summary"] = (
            f"{len(packets)} review item{'s' if len(packets) != 1 else ''} waiting."
            if packets
            else str(cache.get("summary") or "No ticket review packets are waiting.")
        )
        return cache

    def _durable_review_rows(self, *, batch_size: int = 500) -> list[dict[str, object]]:
        """Read every unresolved durable review in bounded SQLite pages."""

        state = getattr(self, "state", None)
        list_review_jobs = getattr(state, "list_review_jobs", None)
        if not callable(list_review_jobs):
            return []
        batch_size = max(1, min(int(batch_size or 500), 1000))
        rows: list[dict[str, object]] = []
        seen_ids: set[int] = set()
        offset = 0
        while True:
            try:
                page = list_review_jobs(limit=batch_size, offset=offset)
            except TypeError:
                # Compatibility with lightweight state fakes and older custom
                # stores that predate paged review reads.
                return list(list_review_jobs(limit=1000))
            if not page:
                break
            for row in page:
                bridge_job_id = int(row.get("id") or 0)
                if bridge_job_id <= 0 or bridge_job_id in seen_ids:
                    continue
                seen_ids.add(bridge_job_id)
                rows.append(row)
            offset += len(page)
            if len(page) < batch_size:
                break
        return rows

    def submit_review_packet_continue(self, payload: dict[str, Any]) -> dict[str, Any]:
        packet_id = str(payload.get("packetId") or payload.get("id") or "").strip()
        packet = self._find_review_packet(packet_id)
        if packet is None:
            raise ValueError("Review packet not found.")
        instruction = str(payload.get("instruction") or "").strip()
        if not instruction:
            raise ValueError("Add a message for the agent before sending a packet follow-up.")
        agent_name = self._review_followup_agent(packet, payload)
        prompt_packet = {**packet, "followupAgentName": agent_name}
        financial_proposal = (
            packet.get("financialActionProposal")
            if isinstance(packet.get("financialActionProposal"), dict)
            else {}
        )
        proposal_hash = str(financial_proposal.get("proposalHash") or "").strip()
        financial_approved = bool(
            proposal_hash and _financial_approval_instruction(instruction, proposal_hash)
        )
        prompt = (
            build_financial_proposal_approval_prompt(prompt_packet, financial_proposal)
            if financial_approved
            else build_review_packet_continue_prompt(prompt_packet, instruction)
        )
        followup_source_type = (
            "review-financial-proposal-approval"
            if financial_approved
            else "review-financial-proposal-followup"
            if financial_proposal
            else "review-packet-continue"
        )
        packet_version = max(0, int(packet.get("reviewVersion") or 0))
        parent_version_value = packet.get("parentReviewVersion")
        parent_review_version = max(
            0,
            int(packet_version if parent_version_value is None else parent_version_value),
        )
        result = self.submit_prompt(
            agent_name=agent_name,
            prompt=prompt,
            payload={
                "type": "review-packet-continue",
                "packetId": packet_id,
                "ticketNumber": packet.get("ticketNumber") or packet.get("number") or "",
                "instruction": instruction,
                "agentName": agent_name,
                "targetAgent": agent_name,
                "originalAgentName": packet.get("agentName") or "",
                "reviewKind": packet.get("kind") or "salesforce_ticket",
                "parentBridgeJobId": packet.get("bridgeJobId") or "",
                "relatedBridgeJobIds": packet.get("relatedBridgeJobIds") or [],
                "reviewVersion": parent_review_version,
                "packetVersion": packet_version,
                "idempotencyKey": _review_packet_attempt_key(packet_id, packet_version),
                "financialActionProposal": financial_proposal,
                "financialProposalHash": proposal_hash,
                "financialProposalApproved": financial_approved,
            },
            source_type=followup_source_type,
        )
        if result.get("duplicate") and str(result.get("sourceType") or "") != followup_source_type:
            return {
                **result,
                "accepted": False,
                "message": "A different review action is already active for this item.",
            }
        self._mark_review_followup_queued(packet, result)
        return result

    def submit_review_packet_close(self, payload: dict[str, Any]) -> dict[str, Any]:
        packet_id = str(payload.get("packetId") or payload.get("id") or "").strip()
        packet = self._find_review_packet(packet_id)
        if packet is None:
            raise ValueError("Review packet not found.")
        if isinstance(packet.get("financialActionProposal"), dict) and packet.get("financialActionProposal"):
            raise ValueError(
                "Financial proposals cannot be executed or closed from this action. Approve the exact proposal hash through Continue, or reject/abandon it."
            )
        instruction = str(payload.get("instruction") or "").strip()
        agent_name = self._review_followup_agent(packet, payload)
        prompt_packet = {**packet, "followupAgentName": agent_name}
        prompt = build_review_packet_close_prompt(prompt_packet, instruction)
        packet_version = max(0, int(packet.get("reviewVersion") or 0))
        parent_version_value = packet.get("parentReviewVersion")
        parent_review_version = max(
            0,
            int(packet_version if parent_version_value is None else parent_version_value),
        )
        result = self.submit_prompt(
            agent_name=agent_name,
            prompt=prompt,
            payload={
                "type": "review-packet-close",
                "packetId": packet_id,
                "ticketNumber": packet.get("ticketNumber") or packet.get("number") or "",
                "instruction": instruction,
                "agentName": agent_name,
                "targetAgent": agent_name,
                "originalAgentName": packet.get("agentName") or "",
                "reviewKind": packet.get("kind") or "salesforce_ticket",
                "parentBridgeJobId": packet.get("bridgeJobId") or "",
                "relatedBridgeJobIds": packet.get("relatedBridgeJobIds") or [],
                "reviewVersion": parent_review_version,
                "packetVersion": packet_version,
                "idempotencyKey": _review_packet_attempt_key(packet_id, packet_version),
            },
            source_type="review-packet-close",
        )
        if result.get("duplicate") and str(result.get("sourceType") or "") != "review-packet-close":
            return {
                **result,
                "accepted": False,
                "message": "A different review action is already active for this item.",
            }
        self._mark_review_followup_queued(packet, result)
        return result

    def submit_review_packet_abandon(self, payload: dict[str, Any]) -> dict[str, Any]:
        packet_id = str(payload.get("packetId") or payload.get("id") or "").strip()
        if not packet_id:
            raise ValueError("Review packet id is required.")
        packet = self._find_review_packet(packet_id)
        if packet is None:
            raise ValueError("Review packet not found.")
        active_status = str(packet.get("activeFollowupStatus") or "").strip().lower()
        active_job_key = str(packet.get("activeFollowupJobId") or "").strip()
        if active_job_key and not active_status:
            active_status = str((self.job(active_job_key) or {}).get("status") or "").strip().lower()
        if active_status in {"queued", "running"} or str(packet.get("status") or "") == "followup_queued":
            raise ValueError("A review follow-up is still active; wait for it to finish before abandoning the parent.")
        if str(packet.get("kind") or "") == "job_outcome":
            bridge_job_ids = _review_packet_bridge_job_ids(packet)
            for bridge_job_id in bridge_job_ids:
                self.state.mark_review_resolved(
                    bridge_job_id,
                    resolution=(
                        "Operator abandoned this recurring review group."
                        if len(bridge_job_ids) > 1
                        else "Operator abandoned this follow-up item."
                    ),
                )
            self._delete_review_packet(packet_id)
        else:
            self._delete_review_packet(packet_id)
        return {
            "ok": True,
            "accepted": True,
            "message": "abandoned",
            "packetId": packet_id,
            "ticketNumber": packet.get("ticketNumber") or packet.get("number") or "",
            "resolvedReviewCount": len(_review_packet_bridge_job_ids(packet)),
        }

    def _review_followup_agent(self, packet: dict[str, Any], payload: dict[str, Any]) -> str:
        """Select an explicit, configured follow-up lane without silent rerouting."""

        requested = str(payload.get("targetAgent") or payload.get("agentName") or "").strip()
        if requested:
            if requested not in self.config.agents:
                raise ValueError(f"Unknown review follow-up agent: {requested}")
            return requested
        original = str(packet.get("agentName") or "").strip()
        if original in self.config.agents:
            return original
        if "tickets_agent" in self.config.agents:
            return "tickets_agent"
        raise ValueError("Review packet has no configured follow-up agent.")

    def _job_record_for_review_row(self, row: dict[str, object]) -> dict[str, Any]:
        """Read local command-center context used to enrich a SQLite review."""

        if str(row.get("channel_id") or "") != "command_center":
            return {}
        job_key = str(row.get("event_id") or "").strip()
        if not job_key:
            return {}
        with self._lock:
            record = dict(self._jobs.get(job_key) or {})
        if record:
            return record
        path = self.jobs_dir / f"{_safe_path_part(job_key)}.json"
        try:
            loaded = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return dict(loaded) if isinstance(loaded, dict) else {}

    def submit_email_scan(self) -> dict[str, Any]:
        if self._inbox_ledger_active():
            return self.collect_inbox_now()
        return self.submit_prompt(
            agent_name="coding_agent",
            prompt=build_ops_email_scan_prompt(self.email_watch_path),
            payload={
                "type": "ops-email-watch-scan",
                "outputPath": str(self.email_watch_path),
            },
            source_type="ops-email-watch",
        )

    def _submit_verified_email_delivery(
        self,
        *,
        agent_name: str,
        job_key: str,
        job_record: dict[str, Any],
        request: dict[str, Any],
        attachments: list[dict[str, Any]],
    ) -> dict[str, Any]:
        source_type = str(job_record.get("sourceType") or "").strip()
        payload = (
            job_record.get("payload")
            if isinstance(job_record.get("payload"), dict)
            else {}
        )
        allowed_recipients = _verified_email_delivery_allowed_recipients(
            agent_name=agent_name,
            source_type=source_type,
            payload=payload,
        )
        recipient = _verified_email_address(request.get("recipient"))
        if recipient.casefold() not in allowed_recipients:
            raise ValueError(
                "The recipient is not present in the verified operator request or its "
                "explicitly referenced ticket/message evidence."
            )

        subject = " ".join(str(request.get("subject") or "").strip().split())
        body = str(request.get("body") or "").strip()
        if not subject or len(subject) > 500 or "\r" in subject or "\n" in subject:
            raise ValueError("A single-line subject of at most 500 characters is required.")
        if not body or len(body) > 12000:
            raise ValueError("A customer-facing body of at most 12,000 characters is required.")
        if _contains_internal_failure_diagnostic(body):
            raise ValueError("Internal failure or review text cannot be sent to a customer.")

        requested_names = request.get("attachmentNames") or []
        if not isinstance(requested_names, list) or len(requested_names) > MAX_AGENT_CHAT_ATTACHMENTS:
            raise ValueError("attachmentNames must be a bounded list.")
        clean_names = [str(value or "").strip() for value in requested_names]
        if any(not name or len(name) > 255 for name in clean_names):
            raise ValueError("One requested attachment name is invalid.")
        if len({name.casefold() for name in clean_names}) != len(clean_names):
            raise ValueError("attachmentNames contains a duplicate.")

        attachments_by_name: dict[str, list[dict[str, Any]]] = {}
        for item in attachments:
            name = str(item.get("name") or "").strip()
            attachments_by_name.setdefault(name.casefold(), []).append(item)
        selected: list[dict[str, Any]] = []
        for name in clean_names:
            matches = attachments_by_name.get(name.casefold()) or []
            if len(matches) != 1:
                raise ValueError(
                    f"The requested attachment {name!r} did not resolve to exactly one verified job file."
                )
            selected.append(matches[0])
        total_bytes = sum(int(item.get("size") or 0) for item in selected)
        if total_bytes > MAX_VERIFIED_EMAIL_ATTACHMENT_BYTES:
            raise ValueError("The selected attachments exceed the guarded email delivery limit.")

        idempotency_key = _verified_email_delivery_action_key(
            job_key=job_key,
            recipient=recipient,
            subject=subject,
            body=body,
            attachments=selected,
        )
        lock = getattr(self, "_email_send_lock", None)
        if lock is None:
            lock = Lock()
            self._email_send_lock = lock
        with lock:
            gmail_result = _gmail_send_signature_preserving_message(
                token_path=Path(self.gmail_token_path),
                journal_path=Path(self.email_send_journal_path),
                recipient=recipient,
                subject=subject,
                body=body,
                attachments=selected,
                idempotency_key=idempotency_key,
            )
        return {
            "ok": True,
            "sent": True,
            "duplicate": bool(gmail_result.get("duplicate")),
            "recipient": recipient,
            "subject": subject,
            "attachmentNames": clean_names,
            "sentMessageId": str(gmail_result.get("id") or ""),
            "threadId": str(gmail_result.get("threadId") or ""),
            "idempotencyKey": idempotency_key,
            "signatureSource": "gmail_send_as",
            "readbackVerified": gmail_result.get("verified") is True,
        }

    def submit_support_email_intake(
        self,
        *,
        message_ids: list[str] | None = None,
        idempotency_key: str = "",
    ) -> dict[str, Any]:
        defaults = getattr(self.config, "defaults", {}) or {}
