    def _stage_billing_closure_email_evidence(
        self,
        item: dict[str, Any],
    ) -> dict[str, Any]:
        message_id = str(item.get("messageId") or "").strip()
        if not re.fullmatch(r"[A-Za-z0-9._:@+-]{1,186}", message_id):
            raise ValueError("Billing closure-email Gmail message id is invalid.")
        token = _gmail_access_token(Path(self.gmail_token_path))
        raw_bytes = _gmail_raw_message_bytes(token, message_id)
        file_name = f"billing-close-confirmation-{message_id}.eml"
        return self.store_agent_chat_attachment(
            raw_bytes,
            content_type="text/plain",
            name=file_name,
        )

    def submit_email_reply(self, payload: dict[str, Any]) -> dict[str, Any]:
        body = str(payload.get("body") or "").strip()
        if not body:
            raise ValueError("Email reply body is required.")
        if len(body) > 12000:
            raise ValueError("Email reply body is too long for guarded send.")
        for internal_field in (
            "agentResult",
            "reviewReason",
            "error",
            "failureText",
            "packetId",
            "sourceJobId",
        ):
            if str(payload.get(internal_field) or "").strip():
                raise ValueError("Internal agent/review fields are not accepted in customer email sends.")
        if _contains_internal_failure_diagnostic(body):
            raise ValueError(
                "Internal failure or review text cannot be sent to a customer. "
                "Keep it in the originating chat or the ticket's internal review packet."
            )
        for recipient_field in ("to", "cc", "bcc", "recipient", "recipients"):
            if str(payload.get(recipient_field) or "").strip():
                raise ValueError("Recipient fields are not accepted. Replies must use the cached Gmail thread only.")
        omitted_recipients = _gmail_reply_omissions(payload)

        cached_email = _match_cached_email(self.email_watch(), payload)
        thread_id = str(cached_email.get("threadId") or cached_email.get("thread_id") or "").strip()
        message_id = str(cached_email.get("id") or cached_email.get("messageId") or cached_email.get("message_id") or "").strip()
        if not thread_id and not message_id:
            raise ValueError("Cached email item is missing a Gmail thread/message id.")

        # Browser-supplied idempotency values are advisory only. The gateway
        # derives the durable key from the verified cache row and exact body.
        idempotency_key = _email_reply_action_key(
            cached_email,
            body,
            omitted_recipients=omitted_recipients,
        )
        lock = getattr(self, "_email_send_lock", None)
        if lock is None:
            lock = Lock()
            self._email_send_lock = lock
        journal_path = getattr(self, "email_send_journal_path", None)
        if journal_path is None:
            journal_path = self.email_watch_path.parent / "email_send_journal.json"
            self.email_send_journal_path = journal_path

        with lock:
            gmail_result = _gmail_send_signature_preserving_reply(
                token_path=self.gmail_token_path,
                journal_path=journal_path,
                cached_email=cached_email,
                body=body,
                idempotency_key=idempotency_key,
                omitted_recipients=omitted_recipients,
            )

        self._remove_cached_email(
            cached_email,
            mailbox_action="replied",
            action_note=f"Sent verified reply: {cached_email.get('subject') or message_id or thread_id}",
        )
        ledger = getattr(self, "inbox_ledger", None)
        if ledger is not None and message_id and ledger.item(message_id):
            ledger.complete(
                message_id,
                result={"gmail": _safe_gmail_result(gmail_result), "action": "replied"},
                write_verified=True,
            )
        return {
            "ok": True,
            "accepted": True,
            "sent": True,
            "duplicate": bool(gmail_result.get("duplicate")),
            "message": "sent_and_verified",
            "emailId": message_id,
            "sentMessageId": gmail_result.get("id") or "",
            "threadId": gmail_result.get("threadId") or thread_id,
            "idempotencyKey": idempotency_key,
            "signatureSource": "gmail_send_as",
            "replyMode": "reply_all",
            "omittedRecipients": omitted_recipients,
            "readbackVerified": True,
            "gmail": _safe_gmail_result(gmail_result),
        }

    def submit_email_mark_read(self, payload: dict[str, Any]) -> dict[str, Any]:
        cached_email = _match_cached_email(self.email_watch(), payload)

        thread_id = str(cached_email.get("threadId") or cached_email.get("thread_id") or "").strip()
        message_id = str(cached_email.get("id") or cached_email.get("messageId") or cached_email.get("message_id") or "").strip()
        if not thread_id and not message_id:
            raise ValueError("Cached email item is missing a Gmail thread/message id.")

        idempotency_key = str(payload.get("idempotencyKey") or payload.get("idempotency_key") or "").strip()
        if not idempotency_key:
            idempotency_key = _email_mark_read_action_key(cached_email)

        gmail_result = self._apply_cached_gmail_label_action(
            cached_email,
            add_label_ids=[],
            remove_label_ids=["UNREAD"],
            action_label="mark_read",
        )
        self._remove_cached_email(
            cached_email,
            mailbox_action="markedRead",
            action_note=f"Marked read: {cached_email.get('subject') or message_id or thread_id}",
        )
        ledger = getattr(self, "inbox_ledger", None)
        if ledger is not None and message_id and ledger.item(message_id):
            ledger.complete(
                message_id,
                result={"gmail": _safe_gmail_result(gmail_result), "action": "marked_read"},
                write_verified=True,
            )
        return {
            "ok": True,
            "accepted": True,
            "message": "marked_read",
            "emailId": message_id,
            "threadId": thread_id,
            "idempotencyKey": idempotency_key,
            "gmail": gmail_result,
        }

    def submit_propelr_nmi_setup(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        thread_id = str(payload.get("threadId") or payload.get("thread_id") or "").strip()
        message_id = str(payload.get("emailId") or payload.get("id") or payload.get("messageId") or payload.get("message_id") or "").strip()
        subject = str(payload.get("subject") or "").strip()
        sender = str(payload.get("from") or payload.get("sender") or "").strip()
        idempotency_key = str(payload.get("idempotencyKey") or payload.get("idempotency_key") or "").strip()
        if not idempotency_key and (message_id or thread_id):
            idempotency_key = _propelr_nmi_setup_action_key(payload)
            cache = _read_cached_json(self.propelr_nmi_path, {})
            if _propelr_nmi_cache_blocked_for_source(cache, message_id, thread_id):
                retry_token = hashlib.sha256(
                    str(cache.get("updatedAtUtc") or cache.get("summary") or "blocked").encode("utf-8")
                ).hexdigest()[:12]
                idempotency_key = f"{idempotency_key}:retry-blocked:{retry_token}"
        defaults = getattr(getattr(self, "config", None), "defaults", {}) or {}
        ticket_classification = {
            "recordType": str(
                defaults.get("ops_propelr_nmi_ticket_record_type")
                or PROPELR_NMI_TICKET_CLASSIFICATION["recordType"]
            ).strip(),
            "mainIssue": str(
                defaults.get("ops_propelr_nmi_ticket_main_issue")
                or PROPELR_NMI_TICKET_CLASSIFICATION["mainIssue"]
            ).strip(),
            "technicalIssue": str(
                defaults.get("ops_propelr_nmi_ticket_technical_issue")
                or PROPELR_NMI_TICKET_CLASSIFICATION["technicalIssue"]
            ).strip(),
        }
        ticket_created_by = str(
            defaults.get("ops_propelr_nmi_ticket_created_by")
            or os.getenv("TICKET_CREATED_BY")
            or ""
        ).strip()

        job_payload: dict[str, Any] = {
            "type": "ops-propelr-nmi-setup",
            "outputPath": str(self.propelr_nmi_path),
            "emailId": message_id,
            "threadId": thread_id,
            "from": sender,
            "subject": subject,
            "ticketClassification": ticket_classification,
            "ticketCreatedBy": ticket_created_by,
            "approvedActions": {
                "scope": "command_center_propelr_nmi_setup_only",
                "gmailRead": True,
                "salesforceRead": True,
                "salesforceTicketCreate": True,
                "gmailMarkReadAfterSalesforceTicketReadback": True,
            },
        }
        if idempotency_key:
            job_payload["idempotencyKey"] = idempotency_key

        return self.submit_prompt(
            agent_name="coding_agent",
            prompt=build_ops_propelr_nmi_setup_prompt(
                self.propelr_nmi_path,
                message_id=message_id,
                thread_id=thread_id,
                sender=sender,
                subject=subject,
                ticket_classification=ticket_classification,
                ticket_created_by=ticket_created_by,
            ),
            payload=job_payload,
            source_type="ops-propelr-nmi-setup",
        )

    def submit_propelr_nmi_mark_read(self, payload: dict[str, Any] | None = None) -> dict[str, Any]:
        payload = dict(payload or {})
        cached_email = _match_propelr_nmi_cached_email(self.propelr_nmi_setup(), payload)
        source_email_id = str(
            cached_email.get("sourceEmailId")
            or cached_email.get("emailId")
            or cached_email.get("id")
            or cached_email.get("messageId")
            or cached_email.get("message_id")
            or ""
        ).strip()
        thread_id = str(cached_email.get("threadId") or cached_email.get("thread_id") or "").strip()
        if not source_email_id and not thread_id:
            raise ValueError("Cached Propelr/NMI email is missing a Gmail thread/message id.")

        mark_read_email = {
            "id": source_email_id,
            "messageId": source_email_id,
            "threadId": thread_id,
            "from": cached_email.get("from") or cached_email.get("sender") or "",
            "subject": cached_email.get("subject") or "",
            "receivedAt": cached_email.get("receivedAt") or cached_email.get("date") or "",
        }
        created_ticket_ids = [
            str(ticket_id).strip()
            for ticket_id in (cached_email.get("createdTicketIds") or cached_email.get("ticketIds") or [])
            if str(ticket_id).strip()
        ]
        idempotency_key = str(payload.get("idempotencyKey") or payload.get("idempotency_key") or "").strip()
        if not idempotency_key:
            idempotency_key = _email_mark_read_action_key(mark_read_email)

        gmail_result = self._apply_cached_gmail_label_action(
            mark_read_email,
            add_label_ids=[],
            remove_label_ids=["UNREAD"],
            action_label="propelr_nmi_mark_read",
        )
        self._record_propelr_nmi_mark_read(cached_email, gmail_result)
        self._remove_cached_email(
            mark_read_email,
            mailbox_action="markedRead",
            action_note=f"Marked Propelr/NMI source email read after verified ticket {', '.join(created_ticket_ids) if created_ticket_ids else ''}".strip(),
        )
        ledger = getattr(self, "inbox_ledger", None)
        if ledger is not None and source_email_id and ledger.item(source_email_id):
            ledger.complete(
                source_email_id,
                result={"gmail": _safe_gmail_result(gmail_result), "createdTicketIds": created_ticket_ids},
                write_verified=True,
            )
        return {
            "ok": True,
            "accepted": True,
            "message": "marked_read",
            "emailId": source_email_id,
            "threadId": thread_id,
            "createdTicketIds": created_ticket_ids,
            "idempotencyKey": idempotency_key,
            "gmail": gmail_result,
        }

