    def submit_ticket_refresh(self) -> dict[str, Any]:
        lock = getattr(self, "_ticket_refresh_lock", None)
        if lock is None:
            lock = Lock()
            self._ticket_refresh_lock = lock
        if not lock.acquire(blocking=False):
            return {
                "accepted": True,
                "completed": False,
                "status": "in_progress",
                "message": "A ticket board refresh is already running.",
            }
        try:
            result = self.refresh_ticket_board_deterministic()
        finally:
            lock.release()
        return {
            **result,
            "accepted": bool(result.get("ok")),
            "completed": bool(result.get("ok")),
            "job_id": f"ticket-sync-{datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')}",
            "message": "Ticket board refreshed from Salesforce and reconciled to Firestore."
            if result.get("ok")
            else "Ticket board refresh could not reach Salesforce; the last durable snapshot was retained.",
        }

    def run_ticket_recon_batch(
        self,
        *,
        limit: int | None = None,
        timeout_seconds: int | None = None,
    ) -> dict[str, Any]:
        """Investigate only new or materially changed live tickets.

        Firestore owns the version claim so overlapping Cloud Scheduler runs do
        not repeat an unchanged ticket.  Each claimed job is kept inside this
        process until terminal state; this is important for CPU-throttled Cloud
        Run services and one-shot Cloud Run Jobs.
        """

        if not _truthy(self.config.defaults.get("ops_ticket_recon_enabled", False)):
            return {"ok": True, "enabled": False, "claimed": 0, "completed": 0}
        if not self.firestore_store.available:
            return {
                "ok": False,
                "enabled": True,
                "claimed": 0,
                "completed": 0,
                "message": "durable_firestore_required",
            }
        batch_limit = max(
            1,
            min(
                int(limit or self.config.defaults.get("ops_ticket_recon_max_per_run", 2)),
                10,
            ),
        )
        wait_limit = max(
            60,
            min(
                int(
                    timeout_seconds
                    or self.config.defaults.get("ops_ticket_recon_job_timeout_seconds", 1500)
                ),
                3000,
            ),
        )
        cache = _read_cached_json(self.tickets_path, {})
        by_lane: dict[str, list[dict[str, Any]]] = {"support": [], "billing": []}
        for column in cache.get("columns") or []:
            if not isinstance(column, dict):
                continue
            for ticket in column.get("tickets") or []:
                if not isinstance(ticket, dict) or _ticket_is_closed(ticket):
                    continue
                lane = "billing" if str(ticket.get("lane") or "").lower() == "billing" else "support"
                by_lane[lane].append(ticket)
        for rows in by_lane.values():
            rows.sort(key=lambda row: (str(row.get("updatedAt") or ""), str(row.get("number") or "")))
        candidates: list[dict[str, Any]] = []
        # Give Alex and Jamie one slot apiece when both lanes changed, then
        # continue round-robin. This prevents a larger support queue from
        # starving billing reconnaissance.
        while any(by_lane.values()):
            for lane in ("support", "billing"):
                if by_lane[lane]:
                    candidates.append(by_lane[lane].pop(0))

        summary: dict[str, Any] = {
            "ok": True,
            "enabled": True,
            "considered": 0,
            "claimed": 0,
            "completed": 0,
            "needsAttention": 0,
            "failed": 0,
            "jobs": [],
        }
        stale_after = int(self.config.defaults.get("ops_ticket_recon_retry_seconds", 7200))
        for ticket in candidates:
            if summary["claimed"] >= batch_limit:
                break
            summary["considered"] += 1
            ticket_id = str(ticket.get("id") or "").strip()
            ticket_number = str(ticket.get("number") or ticket_id).strip()
            lane = "billing" if str(ticket.get("lane") or "").lower() == "billing" else "support"
            agent_name = "billing_agent" if lane == "billing" else "tickets_agent"
            fingerprint = _ticket_recon_fingerprint(ticket)
            if not self.firestore_store.claim_ticket_recon(
                ticket_id,
                fingerprint=fingerprint,
                agent_name=agent_name,
                ticket_number=ticket_number,
                stale_after_seconds=stale_after,
            ):
                continue
            summary["claimed"] += 1
            payload = {
                "type": "salesforce-ticket-agent-prompt",
                "origin": "firestore-ticket-recon",
                "ticketId": ticket_id,
                "ticketNumber": ticket_number,
                "recordType": str(ticket.get("recordType") or ""),
                "accountId": str(ticket.get("accountId") or ""),
                "route": lane,
                "materialHash": fingerprint,
                "idempotencyKey": f"ticket-recon:{ticket_id}:{fingerprint}",
                "approvedActions": {
                    "scope": "proactive_ticket_solution_plan",
                    "salesforceRead": True,
                    "rescueRead": lane == "support",
                    "novaSqlRead": True,
                    "billingRead": lane == "billing",
                    "previewOnly": True,
                    "salesforceWrite": False,
                    "customerMessage": False,
                    "financialWrite": False,
                    "permissionAdministration": False,
                },
            }
            prompt = build_proactive_salesforce_ticket_prompt(payload)
            memory = getattr(self, "resolution_memory", None)
            recall = memory.recall(ticket) if memory is not None else Recall()
            if recall.block:
                prompt = (
                    f"{prompt}\n\n{recall.block}\n\n"
                    "Use that knowledge only to choose which reads to run first and what to verify; "
                    "re-verify against live state, and finish with the required OPERATOR_ACTION_REQUIRED line."
                )
                self.firestore_store.doc_put(
                    self.firestore_store.TICKETS_COLLECTION,
                    ticket_id,
                    {"reconPlaybookIds": recall.playbook_ids},
                )
            queued = self.submit_prompt(
                agent_name=agent_name,
                prompt=prompt,
                payload=payload,
                source_type="ops-salesforce-ticket-investigation",
            )
            job_id = str(queued.get("job_id") or queued.get("jobId") or "").strip()
            if not queued.get("accepted") or not job_id:
                self.firestore_store.complete_ticket_recon(
                    ticket_id,
                    fingerprint=fingerprint,
                    state="failed",
                    result=f"Investigation could not start: {str(queued.get('message') or 'not accepted')[:300]}",
                )
                summary["failed"] += 1
                continue
            self.firestore_store.complete_ticket_recon(
                ticket_id,
                fingerprint=fingerprint,
                state="running",
                job_id=job_id,
            )
            deadline = time.monotonic() + wait_limit
            record = self.job(job_id) or {}
            while str(record.get("status") or "") not in COMMAND_CENTER_TERMINAL_STATUSES:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                record = self.wait_for_job_change(
                    job_id,
                    updated_at=str(record.get("updatedAtUtc") or ""),
                    timeout_seconds=min(20.0, remaining),
                ) or record
            status = str(record.get("status") or "failed").strip().lower()
            result = str(record.get("result") or record.get("error") or "").strip()
            if status in {"completed", "completed_with_issues"}:
                recon_state = "completed" if status == "completed" else "needs_attention"
                summary["completed"] += 1
                if recon_state == "needs_attention":
                    summary["needsAttention"] += 1
            elif status in {"blocked", "recovery_review_required"}:
                recon_state = "needs_attention"
                summary["needsAttention"] += 1
            else:
                recon_state = "failed"
                summary["failed"] += 1
            self.firestore_store.complete_ticket_recon(
                ticket_id,
                fingerprint=fingerprint,
                state=recon_state,
                result=result,
                job_id=job_id,
            )
            summary["jobs"].append(
                {
                    "ticketNumber": ticket_number,
                    "agentName": agent_name,
                    "jobId": job_id,
                    "status": status,
                }
            )
        summary["ok"] = summary["failed"] == 0
        return summary

    def submit_ticket_refresh_with_agent(self) -> dict[str, Any]:
        """Legacy diagnostic path retained for explicit troubleshooting only."""
        output_root = Path(
            getattr(
                self,
                "ticket_refresh_output_root",
                self.tickets_path.parent / "ticket_refresh_outputs",
            )
        ).resolve()
        output_root.mkdir(parents=True, exist_ok=True)
        output_path = output_root / f"ops_tickets.{uuid.uuid4().hex}.json"
        if self.tickets_path.is_file():
            current_cache = _read_cached_json(self.tickets_path, {})
            if current_cache:
                _write_cached_json(output_path, current_cache)
        review_ticket_number_set = {
                str(packet.get("ticketNumber") or packet.get("number") or "").strip()
                for packet in self.review_packets().get("packets") or []
                if _is_salesforce_ticket_number(
                    packet.get("ticketNumber") or packet.get("number") or ""
                )
        }
        for row in self._durable_review_rows():
            source_record = self._job_record_for_review_row(row)
            payload = source_record.get("payload") if isinstance(source_record.get("payload"), dict) else {}
            ticket_number = str(payload.get("ticketNumber") or payload.get("ticket") or "").strip()
            if _is_salesforce_ticket_number(ticket_number):
                review_ticket_number_set.add(ticket_number)
        review_ticket_numbers = sorted(review_ticket_number_set)
        return self.submit_prompt(
            agent_name="tickets_agent",
            prompt=build_ops_ticket_refresh_prompt(
                output_path,
                review_ticket_numbers=review_ticket_numbers,
            ),
            payload={
                "type": "ops-ticket-refresh",
                "outputPath": str(output_path),
                "reviewTicketNumbers": review_ticket_numbers,
            },
            source_type="ops-ticket-refresh",
        )

    def refresh_ticket_board_deterministic(self) -> dict[str, Any]:
        """Deterministically refresh the kanban board without an LLM call.

        Composes the existing typed Salesforce operations (``list_open_tickets``,
        ``read_ticket_feed``, ``read_ticket``) directly in-process, writes the
        same JSON cache the LLM path produced, and upserts the board into the
        durable Firestore ``tickets`` collection when enabled.  This avoids the
        token cost, latency, and non-determinism of routing a pure orchestration
        task through an LLM.

        Returns a summary dict suitable for a job record (``type`` = ``ops-ticket-refresh``).
        """
        started = _utc_now()
        cache: dict[str, Any] = {
            "ok": False,
            "status": "salesforce_unavailable",
            "updatedAtUtc": started,
            "generatedAt": started,
            "source": "deterministic_refresh",
            "total": 0,
            "columns": [],
            "analytics": {"openTickets": 0, "staleTickets": 0, "missingAccount": 0},
            "reviewReconciliation": {"status": "not_run", "checkedAtUtc": started},
        }
        try:
            from scoped_operations_mcp.salesforce_client import (
                SalesforceSettings,
                ScopedSalesforceClient,
            )

            settings = SalesforceSettings.from_environment()
            client = ScopedSalesforceClient(settings)
            open_result = client.list_open_tickets(limit=500)
        except Exception as exc:
            cache["status"] = "salesforce_unavailable"
            cache["source"] = f"deterministic_refresh_error: {type(exc).__name__}"
            self._persist_ticket_cache(cache)
            return {
                "type": "ops-ticket-refresh",
                "deterministic": True,
                "ok": False,
                "status": "salesforce_unavailable",
                "error": type(exc).__name__,
            }

        records = [r for r in open_result.get("records", []) if isinstance(r, dict)]
        columns: dict[str, list[dict]] = {"support": [], "billing": [], "review": []}
        active_numbers: set[str] = set()
        rescue_sessions: dict[str, dict[str, Any]] = {}
        try:
            from rescue_console_mcp.config import Settings as RescueSettings
            from rescue_console_mcp.core import RescueConsoleCore

            rescue_result = RescueConsoleCore(RescueSettings.from_env()).list_sessions()
            rescue_rows = ((rescue_result.get("api") or {}).get("sessions") or [])
            rescue_sessions = {
                str(row.get("sessionId") or "").strip(): dict(row)
                for row in rescue_rows
                if isinstance(row, dict) and str(row.get("sessionId") or "").strip()
            }
        except Exception:
            LOGGER.warning("Rescue session enrichment is unavailable for this ticket refresh")
        for record in records:
            enriched_record = dict(record)
            raw_ticket_id = str(record.get("Id") or record.get("id") or "").strip()
            if raw_ticket_id:
                try:
                    detail_result = client.read_ticket(raw_ticket_id)
                    detail_record = detail_result.get("record") or {}
                    if isinstance(detail_record, dict):
                        # Exact-record reads expose optional fields such as the
                        # Rescue session ID without making the bounded board
                        # query depend on org-specific field accessibility.
                        enriched_record.update(detail_record)
                except Exception:
                    LOGGER.warning(
                        "Optional Salesforce detail enrichment failed for one board ticket"
                    )
            record = enriched_record
            rt = record.get("RecordType") if isinstance(record.get("RecordType"), dict) else {}
            record_type = str(rt.get("Name") or record.get("recordType") or "")
            number = str(record.get("Name") or record.get("Ticket_Number__c") or record.get("number") or "").strip()
            ticket_id = str(record.get("Id") or record.get("id") or "").strip()
            is_closed = bool(record.get("Is_Closed__c") or record.get("isClosed"))
            lane = "billing" if ("Billing" in record_type) else "support"
            if number:
                active_numbers.add(number)
            rescue_session_id = str(record.get("Rescue_Session_ID__c") or "").strip()
            ticket = self._build_ticket_packet(
                record,
                client,
                ticket_id=ticket_id,
                lane=lane,
                rescue_session=rescue_sessions.get(rescue_session_id),
            )
            if is_closed:
                ticket["is_closed"] = True
            columns[lane if lane in columns else "support"].append(ticket)

        review_numbers = sorted(
            {
                str(p.get("ticketNumber") or p.get("number") or "").strip()
                for p in (self.review_packets().get("packets") or [])
                if str(p.get("ticketNumber") or p.get("number") or "").strip()
            }
        )
        reconciliation = {
            "status": "ok",
            "checkedAtUtc": _utc_now(),
            "checkedTicketNumbers": [],
            "closedTicketNumbers": [],
            "openTicketNumbers": [],
            "unresolvedTicketNumbers": [],
        }
        for number in review_numbers:
            reconciliation["checkedTicketNumbers"].append(number)
            if number in active_numbers:
                reconciliation["openTicketNumbers"].append(number)
            else:
                reconciliation["closedTicketNumbers"].append(number)

        for lane_tickets in columns.values():
            for ticket in lane_tickets:
                ticket["reconEvidenceFingerprint"] = _ticket_recon_fingerprint(ticket)
        total = sum(len(v) for v in columns.values())
        cache.update(
            {
                "ok": True,
                "status": "ok",
                "total": total,
                "columns": [
                    {"key": "support", "label": "Support Tickets", "count": len(columns["support"]), "tickets": columns["support"]},
                    {"key": "billing", "label": "Billing Tickets", "count": len(columns["billing"]), "tickets": columns["billing"]},
                    {"key": "review", "label": "Needs Review", "count": len(columns["review"]), "tickets": columns["review"]},
                ],
                "analytics": {"openTickets": total, "staleTickets": 0, "missingAccount": 0},
                "reviewReconciliation": reconciliation,
            }
        )
        self._persist_ticket_cache(cache)

        firestore_result = self._sync_tickets_to_firestore(
            columns["support"] + columns["billing"] + columns["review"],
            active_numbers,
        )

        return {
            "type": "ops-ticket-refresh",
            "deterministic": True,
            "ok": True,
            "status": "ok",
            "total": total,
            "firestore": firestore_result,
            "source": "deterministic_refresh",
        }

    def _sync_tickets_to_firestore(
        self, all_tickets: list[dict[str, Any]], active_numbers: set[str]
    ) -> dict[str, Any]:
        """Persist the board to the durable Firestore store.

        Never raises: Firestore is the scale-to-zero durability layer, and a
        failed write must not break the local cache refresh that already ran.
        Sets an explicit ``is_closed`` flag on every document so the durable
        read path (which filters ``is_closed == False``) can see open tickets.
        """
        store = getattr(self, "firestore_store", None)
        if store is None or not store.available:
            return {"ok": False, "reason": "firestore_unavailable", "written": 0}
        try:
            docs = [
                {**ticket, "is_closed": bool(ticket.get("is_closed") or ticket.get("isClosed"))}
                for ticket in all_tickets
            ]
            result = store.upsert_tickets(docs, ticket_id_key="id")
            if result.get("ok"):
                newly_closed: list[dict[str, Any]] = []
                missing = store.delete_tickets_missing(active_numbers, collect=newly_closed)
                self._learn_from_board_refresh(
                    newly_closed,
                    [str(ticket.get("id") or "") for ticket in all_tickets],
                )
                result = {**result, "closed": missing.get("closed", 0)}
            return result
        except Exception as exc:
            LOGGER.warning("Firestore ticket sync failed: %s", type(exc).__name__)
            return {"ok": False, "reason": f"firestore_sync_error: {type(exc).__name__}", "written": 0}

    def _tickets_from_firestore(self, empty_cache: dict[str, Any]) -> dict[str, Any]:
        """Hydrate the board from the durable Firestore store.

        Container /tmp state is ephemeral: after scale-to-zero the JSON cache
        is gone. When Firestore holds the board, read it back so the dashboard
        shows real tickets immediately, then persist it locally so the rest of
        the instance lifetime reads /tmp instead of Firestore.
        """
        store = getattr(self, "firestore_store", None)
        if store is None or not store.available:
            return empty_cache
        try:
            docs = store.list_tickets(include_closed=False, limit=500)
        except Exception as exc:
            LOGGER.warning("Firestore ticket hydration failed: %s", type(exc).__name__)
            return empty_cache
        if not docs:
            return empty_cache
        by_lane: dict[str, list[dict[str, Any]]] = {"support": [], "billing": [], "review": []}
        for doc in docs:
            lane = str(doc.get("lane") or "support")
            by_lane[lane if lane in by_lane else "support"].append(doc)
        cache = dict(empty_cache)
        cache.update(
            {
                "ok": True,
                "status": "ok",
                "source": "firestore_hydration",
                "updatedAtUtc": _utc_now(),
                "total": sum(len(v) for v in by_lane.values()),
                "columns": [
                    {"key": "support", "label": "Support Tickets", "count": len(by_lane["support"]), "tickets": by_lane["support"]},
                    {"key": "billing", "label": "Billing Tickets", "count": len(by_lane["billing"]), "tickets": by_lane["billing"]},
                    {"key": "review", "label": "Needs Review", "count": len(by_lane["review"]), "tickets": by_lane["review"]},
                ],
            }
        )
        self._persist_ticket_cache(cache)
        return cache

    def _learn_from_board_refresh(
        self,
        newly_closed: list[dict[str, Any]],
        open_ticket_ids: list[str],
    ) -> None:
        """Feed the resolution loop; learning never affects the refresh result."""
        memory = getattr(self, "resolution_memory", None)
        if memory is None or not memory.enabled:
            return
        try:
            reopened = memory.note_reopened(open_ticket_ids)
            captured = memory.capture_closed(newly_closed)
            # Full-collection scans run only when evidence changed (or on the
            # six-hour lifecycle sweep) to stay inside the Firestore free tier.
            playbooks = memory.refresh_playbooks() if (reopened or captured) else {}
            lifecycle: dict[str, int] = {}
            now_monotonic = time.monotonic()
            if now_monotonic - float(getattr(self, "_resolution_lifecycle_at", -1e9)) >= 6 * 3600:
                self._resolution_lifecycle_at = now_monotonic
                lifecycle = memory.apply_lifecycle()
            if reopened or captured or any(playbooks.values()) or any(lifecycle.values()):
                LOGGER.info(
                    "Resolution memory: reopened=%s captured=%s playbooks=%s lifecycle=%s",
                    reopened,
                    captured,
                    playbooks,
                    lifecycle,
                )
        except Exception:
            LOGGER.exception("Resolution memory update failed; board refresh unaffected")

    def _build_ticket_packet(
        self,
        record: dict[str, Any],
        client: Any,
        *,
        ticket_id: str,
        lane: str,
        rescue_session: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Map one Salesforce ticket record into the board cache schema."""
        number = str(record.get("Name") or record.get("number") or ticket_id or "").strip()
        account = record.get("Account__r") if isinstance(record.get("Account__r"), dict) else {}
        record_type = record.get("RecordType") if isinstance(record.get("RecordType"), dict) else {}
        owner = record.get("Owner") if isinstance(record.get("Owner"), dict) else {}
        created_by = record.get("CreatedBy") if isinstance(record.get("CreatedBy"), dict) else {}
        created_at = record.get("CreatedDate") or record.get("createdAt") or ""
        days_active = 0
        created_datetime = _parse_utc_datetime(created_at)
        if created_datetime is not None:
            days_active = max(0, (datetime.now(timezone.utc) - created_datetime).days)
        main_issue = (
            record.get("Tech_Main_Issue__c")
            or record.get("NOVA_Wave_Issue__c")
            or record.get("Main_Issue__c")
            or record.get("mainIssue")
            or ""
        )
        technical_issue = (
            record.get("Technical_Issue__c")
            or record.get("NOVA_Wave_Technical_Issue__c")
            or record.get("technicalIssue")
            or ""
        )
        notes = (
            record.get("Description__c")
            or record.get("Billing_Notes_Internal__c")
            or record.get("Technical_Notes__c")
            or record.get("notesFull")
            or ""
        )
        rescue_session_id = str(record.get("Rescue_Session_ID__c") or "").strip()
        zoom_engagement_id = str(record.get("Zoom_Engagement_ID__c") or "").strip()
        packet: dict[str, Any] = {
            "id": ticket_id or record.get("Id") or "",
            "number": number,
            "url": self._ticket_salesforce_url(ticket_id),
            "createdAt": created_at,
            "updatedAt": record.get("LastModifiedDate") or record.get("updatedAt") or "",
            "daysActive": days_active,
            "account": account.get("Name") or record.get("Account") or record.get("account") or "",
            "accountId": record.get("Account__c") or "",
            "contact": record.get("Customer_Contact__c") or record.get("Contact") or record.get("contact") or "",
            "contactId": record.get("Contact__c") or "",
            "openedBy": created_by.get("Name") or record.get("openedBy") or "",
            "owner": owner.get("Name") or record.get("owner") or "",
            "recordType": record_type.get("Name") or record.get("recordType") or "",
            "status": record.get("Status__c") or record.get("Status") or record.get("status") or "",
            "developmentServiceStatus": record.get("Development_Service_Status__c") or "",
            "isClosed": bool(record.get("Is_Closed__c") or record.get("isClosed")),
            "closedAt": record.get("Ticket_Closed_Date__c") or record.get("ClosedDate") or record.get("closedAt") or "",
            "mainIssue": main_issue,
            "technicalIssue": technical_issue,
            "priority": record.get("Priority__c") or record.get("priority") or "",
            "notesPreview": notes,
            "notesFull": notes,
            "lane": lane,
            "last_seen_at": _utc_now(),
        }
        if rescue_session_id:
            packet["logmeinSessionId"] = rescue_session_id
            packet["rescueSessionId"] = rescue_session_id
            if rescue_session:
                compact_session = self.firestore_store._coerce_doc(
                    {
                        key: rescue_session.get(key)
                        for key in (
                            "sessionId",
                            "status",
                            "entry",
                            "technician",
                            "contactName",
                            "company",
                            "location",
                        )
                        if rescue_session.get(key) not in {None, ""}
                    }
                )
                packet["sessionHistoryItems"] = [compact_session]
                summary_parts = [
                    str(compact_session.get(key) or "").strip()
                    for key in ("status", "technician", "location")
                    if str(compact_session.get(key) or "").strip()
                ]
                packet["sessionHistorySummary"] = " · ".join(summary_parts)
        if zoom_engagement_id:
            packet["zoomEngagementId"] = zoom_engagement_id
        try:
            if ticket_id:
                feed = client.read_ticket_feed(ticket_id, limit=8)
                items = feed.get("items") or feed.get("records") or []
                if items:
                    packet["chatterSummary"] = f"{len(items)} recent comment(s)"
                    packet["chatterItems"] = self.firestore_store._coerce_doc(
                        [dict(i) for i in items if isinstance(i, dict)]
                    )
        except Exception:
            pass
        return packet

    def _ticket_salesforce_url(self, ticket_id: str) -> str:
        if not ticket_id:
            return ""
        return f"https://nova.my.salesforce.com/{ticket_id}"

    def _persist_ticket_cache(self, cache: dict[str, Any]) -> None:
        """Write the board JSON cache to the same path the render path reads."""
        try:
            self.tickets_path.parent.mkdir(parents=True, exist_ok=True)
            _write_cached_json(self.tickets_path, cache)
        except Exception:
            pass
    def _promote_ticket_refresh_cache(self, job_record: dict[str, Any]) -> dict[str, Any]:
        payload = job_record.get("payload") if isinstance(job_record.get("payload"), dict) else {}
        raw_output_path = str(payload.get("outputPath") or "").strip()
        if not raw_output_path:
            raise ValueError("Ticket refresh output path is missing")

        output_root = Path(
            getattr(
                self,
                "ticket_refresh_output_root",
                self.tickets_path.parent / "ticket_refresh_outputs",
            )
        ).resolve(strict=True)
        output_path = Path(raw_output_path).resolve(strict=True)
        try:
            output_path.relative_to(output_root)
        except ValueError as exc:
            raise ValueError("Ticket refresh output escaped its staging root") from exc
        if not output_path.is_file() or output_path.stat().st_size > 16 * 1024 * 1024:
            raise ValueError("Ticket refresh output is missing or too large")

        try:
            cache = json.loads(output_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise ValueError("Ticket refresh output is not valid JSON") from exc
        if not isinstance(cache, dict) or cache.get("ok") is not True:
            raise ValueError("Ticket refresh output did not report a valid result")
        columns = cache.get("columns")
        if not isinstance(columns, list) or not columns:
            raise ValueError("Ticket refresh output is missing ticket columns")
        if any(
            not isinstance(column, dict) or not isinstance(column.get("tickets"), list)
            for column in columns
        ):
            raise ValueError("Ticket refresh output contains invalid ticket columns")

        produced_at = _parse_utc_datetime(cache.get("updatedAtUtc") or cache.get("generatedAt"))
        submitted_at = _parse_utc_datetime(job_record.get("createdAtUtc"))
        if produced_at is None:
            raise ValueError("Ticket refresh output has no valid generation timestamp")
        if submitted_at is not None and produced_at < submitted_at - timedelta(minutes=5):
            raise ValueError("Ticket refresh output was not regenerated for this job")
        if produced_at > datetime.now(timezone.utc) + timedelta(minutes=5):
            raise ValueError("Ticket refresh output timestamp is in the future")

        _write_cached_json(self.tickets_path, cache)
        output_path.unlink(missing_ok=True)
        return cache

