    def submit_singapore_ftp_scan(
        self,
        idempotency_key: str = "",
        singapore_request: Any = None,
        direct_chat_request: bool = False,
    ) -> dict[str, Any]:
        runner_args = self._singapore_ftp_private_runner_args()
        validated_request = _validated_singapore_request(singapore_request)
        runner_args["reactivation_target"] = str(validated_request.get("machineId") or "")
        approved_actions = {
            "scope": "command_center_singapore_ftp_only",
            "gmailRead": True,
            "uploadFailureFiles": True,
            "maintainExistingServerList": True,
            "sendZoomMessageToVerifiedJulio": True,
            "gmailMarkReadCompletedSources": True,
            "gmailMarkReadAutomatedFailures": True,
            "gmailAutoReplyFailedTenants": False,
            "queueTicketAndAlexForIncompleteSources": False,
            "catalogIncompleteSourcesForTaylorStatus": True,
            "suppressOutboundFailureNotifications": True,
            "suppressSharedCustomerAndReviewFailureNotifications": True,
            "queueSalesforceTicketsForOperationalOutcomes": False,
            "queueNeedsReviewForOperationalOutcomes": False,
            "queueTicketOnlyForExplicitNewInterfaceRequest": True,
            "directChatSanitizedOutcomes": True,
            "ignoreVerifiedRetiredInterfaces": True,
        }
        payload = {
            "type": "ops-singapore-ftp-grab-upload",
            "includeNonSubmissions": bool(runner_args["include_non_submissions"]),
            "approvedActions": approved_actions,
            "directChatRequest": bool(direct_chat_request),
        }
        if validated_request:
            payload["singaporeRequest"] = validated_request
        if idempotency_key:
            payload["idempotencyKey"] = idempotency_key
        else:
            local_now = _schedule_watch_local_now(
                str(self.config.defaults.get("ops_singapore_ftp_timezone") or "America/New_York")
            )
            stamp = local_now.strftime("%Y-%m-%dT%H%M%S")
            payload["idempotencyKey"] = f"ops-singapore-ftp-manual:{stamp}:{uuid.uuid4().hex[:8]}"
        return self._submit_singapore_ftp_fast_job(payload=payload, **runner_args)

