def _parse_local_hhmm(value: Any, default_hour: int = 8, default_minute: int = 0) -> tuple[int, int]:
    text = str(value or "").strip()
    if not text:
        return default_hour, default_minute
    match = re.match(r"^(\d{1,2})(?::(\d{1,2}))?$", text)
    if not match:
        return default_hour, default_minute
    hour = max(0, min(23, int(match.group(1))))
    minute = max(0, min(59, int(match.group(2) or "0")))
    return hour, minute


def _ops_weekly_report_window(
    *,
    timezone_name: str = "America/New_York",
    report_weekday: Any = "friday",
    now: datetime | None = None,
) -> dict[str, Any]:
    local_now = _schedule_watch_local_now(timezone_name, now)
    report_weekday_index = _weekday_index(report_weekday, default=4)
    days_since_report_day = (local_now.weekday() - report_weekday_index) % 7
    end_date = local_now.date() - timedelta(days=days_since_report_day)
    start_date = end_date - timedelta(days=7)
    local_tz = local_now.tzinfo
    start_local = datetime.combine(start_date, datetime.min.time(), tzinfo=local_tz)
    end_local = datetime.combine(end_date, datetime.min.time(), tzinfo=local_tz)
    label = f"{start_date.month}/{start_date.day}/{start_date.year}-{end_date.month}/{end_date.day}/{end_date.year}"
    return {
        "timezone": str(timezone_name or "America/New_York"),
        "startDate": start_date.isoformat(),
        "endDate": end_date.isoformat(),
        "startLocal": start_local.isoformat(),
        "endLocal": end_local.isoformat(),
        "startUtc": start_local.astimezone(timezone.utc).isoformat(),
        "endUtc": end_local.astimezone(timezone.utc).isoformat(),
        "label": label,
    }


def _ops_weekly_report_window_key(window: dict[str, Any]) -> str:
    start = _ops_weekly_window_date(window.get("startDate") or window.get("startLocal"))
    end = _ops_weekly_window_date(window.get("endDate") or window.get("endLocal"))
    return f"{_safe_path_part(start)[:40]}:{_safe_path_part(end)[:40]}"


def _ops_weekly_window_date(value: Any) -> str:
    text = str(value or "").strip()
    match = re.match(r"^(\d{4}-\d{2}-\d{2})(?:$|T|\s)", text)
    return match.group(1) if match else text


def _read_ops_weekly_watch_state(path: Path) -> dict[str, Any]:
    try:
        state = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return state if isinstance(state, dict) else {}


def _ops_weekly_auto_report_due(
    state: dict[str, Any],
    *,
    weekday: Any = "friday",
    local_time: Any = "08:00",
    timezone_name: str = "America/New_York",
    now: datetime | None = None,
) -> tuple[bool, str, datetime, dict[str, Any]]:
    local_now = _schedule_watch_local_now(timezone_name, now)
    window = _ops_weekly_report_window(
        timezone_name=timezone_name,
        report_weekday=weekday,
        now=local_now,
    )
    scan_key = _ops_weekly_report_window_key(window)
    due_weekday = _weekday_index(weekday, default=4)
    due_hour, due_minute = _parse_local_hhmm(local_time, default_hour=8, default_minute=0)
    if local_now.weekday() != due_weekday:
        return False, scan_key, local_now, window
    if (local_now.hour, local_now.minute) < (due_hour, due_minute):
        return False, scan_key, local_now, window
    return str(state.get("lastAutoReportWindow") or "") != scan_key, scan_key, local_now, window


def _ops_weekly_report_delivery_verified(report: dict[str, Any], scan_key: str) -> bool:
    report_window = report.get("reportWindow") if isinstance(report.get("reportWindow"), dict) else {}
    zoom_message = report.get("zoomMessage") if isinstance(report.get("zoomMessage"), dict) else {}
    return bool(
        _ops_weekly_report_window_key(report_window) == scan_key
        and zoom_message.get("sent") is True
        and zoom_message.get("readbackVerified") is True
        and str(zoom_message.get("channel") or "").strip().lower() == "zoom"
        and str(zoom_message.get("status") or "").strip().lower() == "sent"
        and str(zoom_message.get("messageId") or "").strip()
    )


def _ops_weekly_retry_allowed(
    state: dict[str, Any],
    scan_key: str,
    local_now: datetime,
    *,
    interval_seconds: int,
) -> bool:
    if str(state.get("pendingReportWindow") or "") != scan_key:
        return True
    attempted_at = _parse_utc_datetime(state.get("lastAttemptAtUtc"))
    if attempted_at is None:
        return True
    attempt_count = max(1, _ops_weekly_attempt_count(state))
    base_delay = max(60, int(interval_seconds or 900))
    retry_delay = min(3600, base_delay * (2 ** min(attempt_count - 1, 2)))
    return local_now.astimezone(timezone.utc) >= attempted_at + timedelta(seconds=retry_delay)


def _ops_weekly_attempt_count(state: dict[str, Any]) -> int:
    try:
        return max(0, int(state.get("attemptCount") or 0))
    except (TypeError, ValueError):
        return 0


def _write_ops_weekly_watch_attempt_state(
    path: Path,
    state: dict[str, Any],
    scan_key: str,
    local_now: datetime,
    window: dict[str, Any],
    result: dict[str, Any],
    *,
    attempt_count: int,
) -> None:
    payload = {
        **state,
        "ok": True,
        "status": "queued",
        "pendingReportWindow": scan_key,
        "attemptCount": int(attempt_count),
        "lastAttemptAtUtc": local_now.astimezone(timezone.utc).isoformat(),
        "lastWindow": window,
        "lastJobId": str(result.get("job_id") or ""),
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def _write_ops_weekly_watch_verified_state(
    path: Path,
    state: dict[str, Any],
    scan_key: str,
    local_now: datetime,
    window: dict[str, Any],
    job_id: str,
    report: dict[str, Any],
) -> None:
    zoom_message = report.get("zoomMessage") if isinstance(report.get("zoomMessage"), dict) else {}
    payload = {
        **state,
        "ok": True,
        "status": "verified",
        "pendingReportWindow": "",
        "lastAutoReportWindow": scan_key,
        "lastAutoReportLocalDate": local_now.date().isoformat(),
        "lastAutoReportLocalWeekday": local_now.strftime("%A").lower(),
        "lastAutoReportAtUtc": datetime.now(timezone.utc).isoformat(),
        "lastWindow": window,
        "lastJobId": str(job_id or ""),
        "lastMessageId": str(zoom_message.get("messageId") or ""),
        "lastDeliveryChannel": "zoom",
        "lastRecipient": str(zoom_message.get("recipient") or ""),
        "lastDeliveryVerified": True,
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False), encoding="utf-8")


def _truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    return str(value or "").strip().lower() in {"1", "true", "yes", "on"}


def _query_value(query: dict[str, list[str]], key: str, default: str = "") -> str:
    values = query.get(key) or []
    return str(values[0]).strip() if values else default


def _query_int(query: dict[str, list[str]], key: str, default: int) -> int:
    try:
        return int(_query_value(query, key, str(default)))
    except (TypeError, ValueError):
        return default


def _job_sort_key(record: dict[str, Any]) -> tuple[str, str]:
    timestamp = (
        str(record.get("updatedAtUtc") or "")
        or str(record.get("createdAtUtc") or "")
        or str(record.get("startedAtUtc") or "")
    )
    return (timestamp, str(record.get("id") or ""))


def _bridge_root_for_config(config_path: Path) -> Path:
    return config_path.parent.parent if config_path.parent.name.lower() == "config" else REPO_ROOT


def _load_runtime_env_files(bridge_root: Path) -> None:
    for env_path in (
        bridge_root / "config" / "ops.env",
        bridge_root / ".env",
        bridge_root / "config" / "logmein-rescue.env",
    ):
        if env_path.exists():
            load_dotenv(env_path, override=False)


def _resolve_runtime_path(bridge_root: Path, raw: Any) -> Path:
    path = Path(str(raw)).expanduser()
    if not path.is_absolute():
        path = bridge_root / path
    return path.resolve()


def _path_is_within(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _safe_path_part(value: str) -> str:
    return "".join(ch if ch.isalnum() or ch in "-_." else "_" for ch in value).strip("._") or "item"


def _utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _normalize_usage_totals(totals: dict) -> dict:
    """Ensure the aggregated usage total always has every counter key."""
    keys = (
        "input_tokens",
        "cached_input_tokens",
        "output_tokens",
        "reasoning_output_tokens",
        "total_tokens",
        "estimated_cost_usd",
    )
    return {key: float(totals.get(key) or 0.0) for key in keys}


def _build_firestore_store_for_runtime() -> FirestoreStore:
    """Build the durable Firestore store used by the runtime.

    Honours the same env config as :func:`build_firestore_store`; the returned
    store is a safe no-op unless ``FIRESTORE_ENABLED`` is set.
    """
    return build_firestore_store()


def _epoch_utc(value: object) -> str:
    try:
        stamp = float(value or 0)
    except (TypeError, ValueError):
        return ""
    if stamp <= 0:
        return ""
    try:
        return datetime.fromtimestamp(stamp, timezone.utc).isoformat()
    except (OverflowError, OSError, ValueError):
        return ""


def _seconds_since_utc(value: str, *, now: float | None = None) -> float:
    try:
        parsed = datetime.fromisoformat(str(value or "").replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return max(0.0, float(now if now is not None else time.time()) - parsed.timestamp())
    except (TypeError, ValueError):
        return float("inf")


def _age_seconds_int(value: str, *, now: float | None = None) -> int:
    age = _seconds_since_utc(value, now=now)
    return int(age) if age != float("inf") else -1


if __name__ == "__main__":
    main()
